#  __BOOT_IMG_B64__  : GRUB 2.12 i386-pc boot.img (MBR boot code)
#  __G_BOOTMGR_B64__ : G-bootmgr from /FILES/BOOTLOADERS/G-bootmgr/G-bootmgr.sh
# ====================================================================
